{
  "summary": "The customer called to report unstable internet dropping every ten minutes and to pay their outstanding balance to avoid service disconnection. The agent identified a signal instability issue at the local exchange, processed the payment, and raised a network ticket to resolve the connection problem.",
  "reasons": [
    {
      "evidence": [
        {
          "turn_id": 2,
          "quote": "My internet has been dropping every ten minutes for the last three days."
        }
      ],
      "label": "network",
      "confidence": 1.0,
      "rationale": "The customer explicitly complained about unstable internet drops."
    },
    {
      "evidence": [
        {
          "turn_id": 9,
          "quote": "I also need to pay my outstanding balance so it doesn't get cut off."
        }
      ],
      "label": "billing",
      "confidence": 1.0,
      "rationale": "The customer made a payment to cover their outstanding balance."
    }
  ],
  "resolution": {
    "evidence": [
      {
        "turn_id": 12,
        "quote": "The payment has been processed successfully. Now, regarding the network issue, I am going to raise a network ticket to have the exchange port reset and monitored."
      }
    ],
    "status": "partial",
    "confidence": 0.9,
    "rationale": "The billing payment was successfully processed, but the network issue requires a follow-up ticket for the exchange port reset and is not instantly fixed during the call."
  },
  "churn": {
    "evidence": [
      {
        "turn_id": 7,
        "quote": "Yes, that is correct. I just want this fixed now."
      }
    ],
    "risk_score": 0.3,
    "flag": false,
    "rationale": "The customer expressed high frustration and demanded a fix, but did not threaten to cancel or switch providers."
  }
}
